      tabs: [
        ["metrics", "Metrics"], ["charts", "Charts"], ["calendar", "Calendar"],
        ["journey", "Journey"], ["photos", "Photos"], ["transformation", "Transformation"],
      ].map(([key, label]) => ({ key, label, active: tab === key })),
